import{_ as i,o as s,c as a,a2 as t}from"./chunks/framework.ChIlRNAd.js";const u=JSON.parse('{"title":"API Vie privée — sortie du chiffrement des archives","description":"","frontmatter":{},"headers":[],"relativePath":"fr/technical/api/privacy.md","filePath":"fr/technical/api/privacy.md"}'),r={name:"fr/technical/api/privacy.md"};function n(c,e,o,h,l,p){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="api-vie-privee-—-sortie-du-chiffrement-des-archives" tabindex="-1">API Vie privée — sortie du chiffrement des archives <a class="header-anchor" href="#api-vie-privee-—-sortie-du-chiffrement-des-archives" aria-label="Permalink to &quot;API Vie privée — sortie du chiffrement des archives&quot;">​</a></h1><h2 id="prefixe-api-privacy" tabindex="-1">Préfixe : <code>/api/privacy</code> <a class="header-anchor" href="#prefixe-api-privacy" aria-label="Permalink to &quot;Préfixe : `/api/privacy`&quot;">​</a></h2><p>Session uniquement (refusé aux jetons d&#39;API).</p><p>Le <strong>chiffrement des archives a été retiré</strong> de Nid : il ne protégeait que le contenu des fichiers EML (objet, expéditeur, destinataires, extrait et noms des pièces jointes restaient en clair dans PostgreSQL), et il rendait le mail illisible dans Nid, introuvable par la recherche plein texte et impossible à restaurer ou à partager. Pour protéger les archives au repos, chiffrez le volume du NAS (LUKS, dataset ZFS chiffré…) : cela couvre aussi la base. Seule la sortie reste : remettre en clair les archives déjà chiffrées.</p><hr><h3 id="get-accountid-encryption-status" tabindex="-1"><code>GET /:accountId/encryption/status</code> <a class="header-anchor" href="#get-accountid-encryption-status" aria-label="Permalink to &quot;`GET /:accountId/encryption/status`&quot;">​</a></h3><p>Nombre d&#39;archives du compte encore chiffrées.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;total&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;encrypted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;unencrypted&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;percentage&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">80</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="post-accountid-encryption-decrypt-all" tabindex="-1"><code>POST /:accountId/encryption/decrypt-all</code> <a class="header-anchor" href="#post-accountid-encryption-decrypt-all" aria-label="Permalink to &quot;`POST /:accountId/encryption/decrypt-all`&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;passphrase&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ma-phrase-secrète&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Vérifie la phrase secrète (<code>403</code> sinon), puis lance un job <code>decrypt_archives</code> (<strong>202</strong> <code>{ &quot;jobId&quot; }</code>) qui déchiffre sur place chaque EML et ses pièces jointes, marque l&#39;archive lisible, puis relance le remplissage du texte intégral (<code>backfill_body_text</code>) pour la recherche. Une phrase fausse n&#39;écrit rien (tag GCM). La phrase n&#39;est ni stockée dans la table <code>jobs</code> ni conservée dans Redis après le job. Rate limit : 5/min. Interface : Paramètres › Données › <strong>Archives chiffrées</strong> (affichée seulement s&#39;il en reste).</p><hr><h2 id="format-du-fichier-chiffre" tabindex="-1">Format du fichier chiffré <a class="header-anchor" href="#format-du-fichier-chiffre" aria-label="Permalink to &quot;Format du fichier chiffré&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GMENC01 (7 octets magic) | SALT (32 octets) | IV (12 octets) | TAG (16 octets) | CIPHERTEXT</span></span></code></pre></div><ul><li>Algorithme : AES-256-GCM</li><li>Dérivation de clé : PBKDF2 (SHA-512, 100 000 itérations)</li><li>La phrase secrète n&#39;est jamais stockée, seul un hash scrypt est conservé pour vérification</li></ul>',15)])])}const k=i(r,[["render",n]]);export{u as __pageData,k as default};
